-- Per-country prices and the new test catalogue (B2C Test Master).
--
-- Run after 0003_tests.sql. In one transaction it:
--   1. swaps the old panels inside sub-profiles and profiles for the single tests they
--      contained (Lipid Profile -> Total Cholesterol, Triglycerides, HDL, LDL, ...);
--   2. replaces the tests with the 122 from the test master: a price and report time for
--      each country (AE, SA, BH), no MRP, and the popularity rank in sort_order;
--   3. gives profiles a price per country instead of one rupee price, starting from what
--      their tests cost together (lower them in the admin to the real offer prices);
--   4. updates save_profile to store those prices.
-- Must match OLD_TEST_IDS in server/catalog.js and src/data/tests.json.

begin;

-- 1. Old panel ids -> the single tests that replace them.
create temp table old_test_ids (old text primary key, new text[] not null) on commit drop;

-- The ids with each old panel expanded, in order, without repeats.
create function pg_temp.remap_tests(ids text[]) returns text[] language sql stable as $$
  select coalesce(array_agg(id order by pos), '{}')
  from (
    select x.id, min(t.ord * 100 + x.k) as pos
    from unnest(ids) with ordinality as t(old, ord)
    left join old_test_ids m on m.old = t.old
    cross join lateral unnest(coalesce(m.new, array[t.old])) with ordinality as x(id, k)
    group by x.id
  ) s;
$$;

update public.sub_profile_library set test_ids = pg_temp.remap_tests(test_ids), updated_at = now();
update public.profiles set test_ids = pg_temp.remap_tests(test_ids);

-- 2. The new catalogue.
alter table public.tests
  add column prices jsonb not null default '{}',
  add column tats jsonb not null default '{}',
  drop column price,
  drop column mrp,
  drop column tat;

delete from public.tests;


-- 3. Profile prices per country, starting from the sum of their tests.
alter table public.profiles add column prices jsonb not null default '{}';

update public.profiles p set prices = (
  select jsonb_build_object(
    'AE', coalesce(round(sum((t.prices->>'AE')::numeric)), 0),
    'SA', coalesce(round(sum((t.prices->>'SA')::numeric)), 0),
    'BH', coalesce(round(sum((t.prices->>'BH')::numeric), 2), 0))
  from public.tests t
  where t.id in (
    select unnest(p.test_ids)
    union
    select unnest(l.test_ids)
    from public.profile_sub_profiles ps
    join public.sub_profile_library l on l.id = ps.sub_profile_id
    where ps.profile_id = p.id));

alter table public.profiles drop column price;

-- 4. Saves a profile and replaces its sub-profile links in one transaction.
-- payload: { id, name, tag, category, tagline, prices: { AE, SA, BH }, icon, hue, sort_order,
--            published, test_ids: [test id], sub_profile_ids: [library id] }
create or replace function public.save_profile(payload jsonb)
returns void
language plpgsql
set search_path = public
as $$
begin
  values (
    payload->>'id', payload->>'name', payload->>'tag', payload->>'category', payload->>'tagline',
    payload->'prices', payload->>'icon', (payload->>'hue')::smallint,
    (payload->>'sort_order')::integer, (payload->>'published')::boolean,
    array(select jsonb_array_elements_text(payload->'test_ids'))
  )
  on conflict (id) do update set
    name = excluded.name, tag = excluded.tag, category = excluded.category,
    tagline = excluded.tagline, prices = excluded.prices, icon = excluded.icon,
    hue = excluded.hue, sort_order = excluded.sort_order, published = excluded.published,
    test_ids = excluded.test_ids, updated_at = now();

  delete from profile_sub_profiles where profile_id = payload->>'id';

  select payload->>'id', (v #>> '{}')::bigint, (ord - 1)::integer
  from jsonb_array_elements(payload->'sub_profile_ids') with ordinality as t(v, ord);
end;
$$;

revoke execute on function public.save_profile(jsonb) from public, anon, authenticated;

commit;
